{
  "name": "opencode-buddy",
  "version": "0.6.2",
  "description": "A virtual ASCII pet companion that lives in the opencode TUI sidebar. Hatches, feeds, plays, and reacts to what you're coding.",
  "type": "module",
  "main": "src/server-plugin.js",
  "exports": {
    ".": "./src/server-plugin.js",
    "./tui": "./src/tui-plugin.jsx",
    "./package.json": "./package.json"
  },
  "files": [
    "src",
    "scripts",
    "assets",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "pet",
    "tamagotchi",
    "ascii",
    "companion",
    "buddy",
    "virtual-pet",
    "sidebar"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "postinstall": "node scripts/postinstall.mjs"
  },
  "author": "AMark-CS",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AMark-CS/opencode-buddy.git"
  },
  "bugs": {
    "url": "https://github.com/AMark-CS/opencode-buddy/issues"
  },
  "homepage": "https://github.com/AMark-CS/opencode-buddy#readme",
  "dependencies": {
    "@opentui/solid": "^0.3.1"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  }
}
